function parseInput(text) {
  var lines = String(text).replace(/\r\n?/g, '\n').split('\n');
  var rows = [], errors = [], notes = [], seenData = false;
  for (var i = 0; i < lines.length; i++) {
    var raw = lines[i], lineNo = i + 1;
    if (!raw.trim()) continue;
    var sp = splitFields(raw);
    if (sp.error) { errors.push({ line: lineNo, text: raw, message: 'line ' + sp.error + '.' }); seenData = true; continue; }
    var f = sp.fields;
    // A header row (first data line, no numeric count fields) is ignored and reported.
    if (!seenData && f.length >= 4 && f.slice(1, 5).every(function (s) { return !looksNumeric(s); }) && !looksNumeric(f[0])) {
      seenData = true; notes.push('Line ' + lineNo + ' looks like a header row and was ignored.'); continue;
    }
    seenData = true;
    var label, counts;
    // A quoted first field in a five-field row is a canonical study label, even if n2 is missing.
    if (f.length === 5 && (sp.firstQuoted || !(looksNumeric(f[0]) && !looksNumeric(f[4])))) { label = f[0]; counts = f.slice(1, 5); }
    else if ((f.length === 5 || f.length === 4) && looksNumeric(f[0])) { counts = f.slice(0, 4); label = f.length === 5 ? f[4] : ''; }
    else {
      errors.push({ line: lineNo, text: raw, message: 'expected 5 values (study, e1, n1, e2, n2) but found ' + f.length + '.' });
      continue;
    }
    var names = ['e1', 'n1', 'e2', 'n2'], vals = [], bad = [];
    for (var j = 0; j < 4; j++) {
      var s = counts[j];
      if (s === '') bad.push(names[j] + ' is empty');
      else if (!isCount(s)) bad.push(names[j] + ' = "' + s + '" is not a whole number' + (/^-/.test(s) ? ' (negative)' : (/[.,]\d/.test(s) || /\d\.\d*$/.test(s) ? ' (decimals are not rounded or truncated)' : '')));
      else if (!Number.isSafeInteger(Number(s))) bad.push(names[j] + ' = "' + s + '" is too large');
      vals.push(Number(s));
    }
    if (!bad.length) {
      if (vals[1] < 1) bad.push('n1 must be at least 1');
      if (vals[3] < 1) bad.push('n2 must be at least 1');
      if (vals[0] > vals[1]) bad.push('e1 (' + vals[0] + ') is larger than n1 (' + vals[1] + ')');
      if (vals[2] > vals[3]) bad.push('e2 (' + vals[2] + ') is larger than n2 (' + vals[3] + ')');
    }
    if (bad.length) { errors.push({ line: lineNo, label: label, text: raw, message: bad.join('; ') + '.' }); continue; }
    rows.push({ e1: vals[0], n1: vals[1], e2: vals[2], n2: vals[3], label: label || ('Study ' + (rows.length + 1)), line: lineNo });
  }
  return { rows: rows, errors: errors, notes: notes };
}
